import { useState, useEffect } from "react";

export const useScrolledPast = (threshold = 0) => {
  const [isScrolledPast, setIsScrolledPast] = useState(false);
  useEffect(() => {
    const handleScroll = () => {
      setIsScrolledPast(window.scrollY > threshold);
    };
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, [threshold]);
  return isScrolledPast;
};

"use client";

import { LucideMenu } from "lucide-react";
import type { ReactNode } from "react";
import { useState } from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";
import { useScrolledPast } from "@/registry/hooks/useScrolledPast";
import { BottomDrawer } from "@/registry/new-york/bottom-drawer/BottomDrawer";
import { CustomButton } from "@/registry/new-york/custom-button/CustomButton";

export interface PageHeaderClassNames {
  root?: string;
  container?: string;
  leftSide?: string;
  middle?: string;
  rightSide?: string;
  menuButton?: string;
  pastScrolled?: string;
}

export interface PageHeaderProps {
  leftSide?: ReactNode;
  middle?: ReactNode;
  drawerContent?: ReactNode | undefined;
  classNames?: PageHeaderClassNames;
  height?: number;
  fixedOnScroll?: boolean;
  renderRightSide?: (props: {
    menuButton: ReactNode;
    bottomDrawer: (children: ReactNode) => ReactNode;
  }) => ReactNode;
}

export const PageHeader: ReactFC<PageHeaderProps> = ({
  leftSide,
  middle,
  drawerContent,
  classNames,
  renderRightSide,
  height = 80,
  fixedOnScroll = false,
}) => {
  const isScrolled = useScrolledPast(height);
  const [isOpen, setIsOpen] = useState(false);

  const menuButton = (
    <CustomButton
      variant="ghost"
      leftIcon={LucideMenu}
      className={cn(classNames?.menuButton)}
      aria-label="Menu"
      iconSize={20}
    />
  );

  const bottomDrawer = (children: ReactNode) => (
    <BottomDrawer open={isOpen} onOpenChange={setIsOpen} trigger={menuButton}>
      {children}
    </BottomDrawer>
  );

  const applyFixed = fixedOnScroll ? isScrolled : false;

  return (
    <div
      style={{
        height,
      }}
      className={cn(
        "z-30 flex w-full items-center justify-between",
        "backdrop-blur-xl transition-all duration-200",
        "text-foreground/80",
        {
          "r-0 dark:bg-background/80 fixed top-0 left-0 shadow-sm": applyFixed,
        },
        classNames?.root
      )}
    >
      <div
        className={cn(
          "flex w-full max-w-[1200px] items-center justify-between px-4 py-3",
          classNames?.container
        )}
      >
        <div className={cn("flex-1", classNames?.leftSide)}>{leftSide}</div>

        {middle && (
          <div className={cn("flex-1 text-center", classNames?.middle)}>
            {middle}
          </div>
        )}

        <div className={cn("flex flex-1 justify-end", classNames?.rightSide)}>
          {renderRightSide?.({ bottomDrawer, menuButton }) ??
            (drawerContent ? bottomDrawer(drawerContent) : null)}
        </div>
      </div>
    </div>
  );
};

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
